// AUTO-GENERATED by sync-opencode-from-cc.py
// Claude Code 正本の hook 方針を OpenCode plugin へ最小変換した派生物。
// OpenCode v1.19.0（default.server）と v2（default.setup）の両方で読み込める形。
import { spawnSync } from "node:child_process"
import { existsSync } from "node:fs"

const RUNTIME_SPEC = {
  "before": {
    "block_main_commit": true,
    "block_destructive_git": true,
    "pre_pr_check_on_git_push": false
  },
  "after": {
    "write_edit": {
      "auto_catalog": false,
      "check_frontmatter": false,
      "validate_skills": false,
      "validate_ssot": false,
      "validate_prompt_ssot": false
    }
  }
}

function parseHookDeny(stdout) {
  if (!stdout) return null
  try {
    const payload = JSON.parse(stdout)
    const hs = payload && payload.hookSpecificOutput
    if (hs && hs.permissionDecision === "deny") {
      return String(hs.permissionDecisionReason || hs.reason || "blocked by Claude-compatible hook")
    }
  } catch (e) {}
  return null
}

function runProcess(root, command, args = [], {
  cwd = root,
  env = {},
  stdin = "",
  blockOnError = false,
} = {}) {
  const result = spawnSync(command, args, {
    cwd,
    env: { ...process.env, ...env },
    encoding: "utf-8",
    input: stdin,
  })

  if (blockOnError) {
    const deny = parseHookDeny(result.stdout)
    if (deny) throw new Error(deny)
  }

  if (result.status === 0) {
    return
  }

  const message =
    [result.stdout, result.stderr].filter(Boolean).join("\n").trim() ||
    `command failed: ${command} ${args.join(" ")}`
  if (blockOnError) {
    throw new Error(message)
  }
  console.warn(message)
}

function buildHookPayload(command, cwd) {
  return JSON.stringify({
    tool_input: {
      command,
      cwd,
    },
  })
}

function resolveHookScript(root, name) {
  const candidates = [
    `${root}/.claude/hooks/scripts/${name}`,
    `${root}/hook-library/scripts/${name}`,
  ]
  for (const candidate of candidates) {
    if (existsSync(candidate)) return candidate
  }
  return candidates[0]
}

function extractPathsFromPatch(patchText) {
  const paths = new Set()
  for (const line of String(patchText || "").split("\n")) {
    const match = line.match(/^\*\*\* (?:Add File|Update File|Delete File): (.+)$/)
    if (match) {
      paths.add(match[1])
    }
  }
  return [...paths]
}

function validatePath(root, filePath) {
  if (!filePath) return
  const normalizedPath = String(filePath)

  if (RUNTIME_SPEC.after.write_edit.auto_catalog) {
    runProcess(root, "bash", [`${root}/scripts/auto-catalog-trigger.sh`], { cwd: root })
  }

  if (RUNTIME_SPEC.after.write_edit.check_frontmatter && /skills\/.*SKILL\.md$/.test(normalizedPath)) {
    runProcess(
      root,
      "python3",
      [`${root}/scripts/check_frontmatter.py`, "--warn", normalizedPath],
      {
        cwd: root,
        env: { CLAUDE_FILE_PATH: normalizedPath },
      },
    )
  }

  if (RUNTIME_SPEC.after.write_edit.validate_skills && /skills\/.*SKILL\.md$/.test(normalizedPath)) {
    runProcess(
      root,
      "bash",
      [`${root}/scripts/validate-skills.sh`, "--warn", normalizedPath],
      {
        cwd: root,
        env: { CLAUDE_FILE_PATH: normalizedPath },
      },
    )
  }

  if (
    RUNTIME_SPEC.after.write_edit.validate_ssot &&
    /(DISTRIBUTION\.yaml|project-registry\.yaml|hook-registry\.yaml)$/.test(normalizedPath)
  ) {
    runProcess(root, "bash", [`${root}/scripts/validate-ssot-consistency.sh`], { cwd: root })
  }

  if (RUNTIME_SPEC.after.write_edit.validate_prompt_ssot && /snippet-prompts\/.*\.md$/.test(normalizedPath)) {
    runProcess(
      root,
      "bash",
      [`${root}/scripts/validate-prompt-ssot-consistency.sh`, "--warn", normalizedPath],
      {
        cwd: root,
        env: { CLAUDE_FILE_PATH: normalizedPath },
      },
    )
  }
}

function checkShellCommand(root, command, cwd) {
  if (RUNTIME_SPEC.before.block_main_commit) {
    runProcess(
      root,
      "bash",
      [resolveHookScript(root, "block-main-commit.sh")],
      {
        cwd: root,
        stdin: buildHookPayload(command, cwd),
        blockOnError: true,
      },
    )
  }

  if (RUNTIME_SPEC.before.block_destructive_git) {
    runProcess(
      root,
      "bash",
      [resolveHookScript(root, "block-destructive-git.sh")],
      {
        cwd: root,
        stdin: buildHookPayload(command, cwd),
        blockOnError: true,
      },
    )
  }

  if (RUNTIME_SPEC.before.pre_pr_check_on_git_push && command.includes("git push")) {
    runProcess(
      root,
      "bash",
      [`${root}/scripts/pre-pr-check.sh`],
      {
        cwd: root,
        blockOnError: true,
      },
    )
  }
}

function validatePatch(root, patchText) {
  for (const filePath of extractPathsFromPatch(patchText)) {
    validatePath(root, filePath)
  }
}

// v1 形式（OpenCode 1.x）: 従来どおり process.cwd() を root にする。
export const RuntimeSyncPlugin = async () => {
  const root = process.cwd()
  return {
    "tool.execute.before": async (input, output) => {
      if (input.tool !== "bash") return

      const command = String(output.args?.command || "")
      const cwd = String(output.args?.cwd || root)
      checkShellCommand(root, command, cwd)
    },

    "tool.execute.after": async (input, output) => {
      if (input.tool === "write" || input.tool === "edit") {
        validatePath(root, output.args?.filePath || output.args?.path)
        return
      }

      if (input.tool === "apply_patch") {
        validatePatch(root, output.args?.patchText || output.patchText)
      }
    },
  }
}

// v2 形式（OpenCode 2.x）: root は ctx.location.directory。
// v2 の共有サーバーは HOME へ chdir するため process.cwd() は使わない。
async function setupRuntimeSync(ctx) {
  const root = String(ctx?.location?.directory || process.cwd())

  await ctx.tool.hook("execute.before", async (event) => {
    if (event.tool !== "shell") return

    const input = event.input || {}
    const command = String(input.command || "")
    const cwd = String(input.workdir || root)
    checkShellCommand(root, command, cwd)
  })

  await ctx.tool.hook("execute.after", async (event) => {
    const input = event.input || {}
    if (event.tool === "write" || event.tool === "edit") {
      validatePath(root, input.path)
      return
    }

    if (event.tool === "patch") {
      validatePatch(root, input.patchText)
    }
  })
}

export default {
  id: "agent-hub-runtime-sync",
  server: RuntimeSyncPlugin,
  setup: setupRuntimeSync,
}
